+        BlockNode irBlockNode = irWhileLoopNode.getBlockNode();
+
+        if (irBlockNode != null) {
+            visit(irBlockNode, writeScope.newLoopScope(begin, end));
+        }
+
+        if (irBlockNode == null || irBlockNode.doAllEscape() == false) {
+            methodWriter.goTo(begin);
+        }
+
+        methodWriter.mark(end);
