+        if (irForEachSubIterableNode.getMethod() == null) {
+            Type methodType = Type.getMethodType(Type.getType(Iterator.class), Type.getType(Object.class));
+            methodWriter.invokeDefCall("iterator", methodType, DefBootstrap.ITERATOR);
