+
+        if (irInvokeCallNode.getBox().isPrimitive()) {
+            methodWriter.box(MethodWriter.getType(irInvokeCallNode.getBox()));
+        }
+
+        for (ExpressionNode irArgumentNode : irInvokeCallNode.getArgumentNodes()) {
